export function normalizeLocationText(text: string): string {
  return text
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .trim()
}

export function resolveLocation(query: string): {
  cityId: number
  barrioId: number
  cityName?: string
  barrioName?: string
} {
  const clean = normalizeLocationText(query)
  if (!clean) return { cityId: 0, barrioId: 0 }

  const parts = clean
    .split(",")
    .map((p) => p.trim())
    .filter(Boolean)

  // 1. Exact match for a whole CITY (e.g. "Envigado", "Medellín", "Bello", "Sabaneta", "Itagüí", "Bogotá")
  // Takes precedence when the query is just the city name
  for (const city of SIMI_LOCATIONS) {
    const normCity = normalizeLocationText(city.nombre)
    if (clean === normCity || (parts.length === 1 && parts[0] === normCity)) {
      return {
        cityId: Number(city.id),
        barrioId: 0,
        cityName: city.nombre,
      }
    }
  }

  // Common city aliases
  if (clean === "itagui")
    return { cityId: 26001, barrioId: 0, cityName: "Itagüí" }
  if (clean === "bogota")
    return { cityId: 11001, barrioId: 0, cityName: "Bogotá" }
  if (clean === "medellin")
    return { cityId: 25974, barrioId: 0, cityName: "Medellín" }

  // 2. Check for explicit "Barrio, Ciudad" or distinct barrio in that city
  for (const city of SIMI_LOCATIONS) {
    const normCity = normalizeLocationText(city.nombre)
    for (const barrio of city.barrios) {
      const normBarrio = normalizeLocationText(barrio.nombre)
      if (
        clean === `${normBarrio}, ${normCity}` ||
        clean === `${normBarrio} ${normCity}` ||
        (parts.length > 1 && parts.includes(normBarrio))
      ) {
        return {
          cityId: Number(city.id),
          barrioId: Number(barrio.id),
          cityName: city.nombre,
          barrioName: barrio.nombre,
        }
      }
    }
  }

  // 3. Check if query is a distinct neighborhood name (length >= 4, and NOT just the city name)
  for (const city of SIMI_LOCATIONS) {
    const normCity = normalizeLocationText(city.nombre)
    for (const barrio of city.barrios) {
      const normBarrio = normalizeLocationText(barrio.nombre)
      if (normBarrio !== normCity && normBarrio.length >= 4) {
        if (clean === normBarrio || clean.includes(normBarrio)) {
          return {
            cityId: Number(city.id),
            barrioId: Number(barrio.id),
            cityName: city.nombre,
            barrioName: barrio.nombre,
          }
        }
      }
    }
  }

  // 4. Fallback city match (if query contains city name)
  for (const city of SIMI_LOCATIONS) {
    const normCity = normalizeLocationText(city.nombre)
    if (clean.includes(normCity)) {
      return {
        cityId: Number(city.id),
        barrioId: 0,
        cityName: city.nombre,
      }
    }
  }

  // 5. Special aliases
  if (clean.includes("poblado"))
    return {
      cityId: 25974,
      barrioId: 6196,
      cityName: "Medellín",
      barrioName: "Poblado",
    }
  if (clean.includes("laureles"))
    return {
      cityId: 25974,
      barrioId: 6563,
      cityName: "Medellín",
      barrioName: "Laureles",
    }
  if (clean.includes("colores"))
    return {
      cityId: 25974,
      barrioId: 6551,
      cityName: "Medellín",
      barrioName: "Los Colores",
    }
  if (clean.includes("belen"))
    return {
      cityId: 25974,
      barrioId: 6178,
      cityName: "Medellín",
      barrioName: "Belén",
    }

  return { cityId: 0, barrioId: 0 }
}

export const PROPERTY_TYPES_MAP: Record<string, number> = {
  apartamento: 1,
  casa: 2,
  consultorio: 3,
  oficina: 4,
  local: 5,
  bodega: 6,
  lote: 7,
  finca: 8,
  edificio: 10,
  apartaestudio: 11,
}

export function resolvePropertyTypeId(type: string): number {
  const clean = normalizeLocationText(type)
  return PROPERTY_TYPES_MAP[clean] || 0
}
